text:
Writing the error boundary component.

## Tool: Write

```json
{
  "file_path": "/repo/ErrorBoundary.tsx",
  "content": "import { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('[ErrorBoundary]', error, info.componentStack);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      if (fallback) return fallback(error, this.reset);
      return (
        <div role="alert" style={{ padding: '1rem', border: '1px solid #f00' }}>
          <p><strong>Something went wrong.</strong></p>
          <pre style={{ fontSize: '0.8rem', opacity: 0.7 }}>{error.message}</pre>
          <button onClick={this.reset}>Retry</button>
        </div>
      );
    }

    return children;
  }
}
"
}
```

Done. `ErrorBoundary.tsx` created with:

- **`getDerivedStateFromError`** — captures error into state, triggers fallback render
- **`componentDidCatch`** — logs error + component stack to console
- **`reset()`** — clears error state on retry
- **Custom fallback prop** — optional `(error, reset) => ReactNode` for full control

**Usage:**
```tsx
// Default fallback UI
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary fallback={(err, retry) => (
  <div>
    <p>{err.message}</p>
    <button onClick={retry}>Try again</button>
  </div>
)}>
  <MyComponent />
</ErrorBoundary>
```
